import type { CartLine } from '#shared/types/cart'
import type { Order, OrderLine } from '#shared/types/order'
import { randomUUID } from 'node:crypto'
import { findProduct } from '#server/utils/db'
import { computeQuote } from '#server/utils/quote'

/** Orders live in server memory only, so they are lost on restart. */
const orders = new Map<string, Order>()

/** Resolves the lines against the catalogue. Returns undefined when a product is unknown. */
export function resolveLines(lines: CartLine[]): OrderLine[] | undefined {
  const resolved: OrderLine[] = []
  for (const line of lines) {
    const product = findProduct(line.slug)
    if (!product)
      return undefined
    resolved.push({ slug: product.slug, name: product.name, qty: line.qty })
  }
  return resolved
}

/** Stores an order priced by the same rules as the quote API. */
export function createOrder(lines: OrderLine[], code?: string): Order {
  const quote = computeQuote(lines, code)
  const order: Order = { id: randomUUID(), lines, ...quote }
  orders.set(order.id, order)
  return order
}

export function getOrder(id: string): Order | undefined {
  return orders.get(id)
}
